import { copy } from '../copy/en';
export class ApiError extends Error {
  constructor(public status: number, public code: string, message: string, public details?: unknown) { super(message); }
}
export class NetworkError extends ApiError { constructor(){ super(0,'NETWORK_UNAVAILABLE', copy.errors.network); } }

const API_BASE = (import.meta.env.VITE_API_BASE_URL as string | undefined) ?? '/api';

interface RequestOptions { method?: string; body?: unknown; idempotencyKey?: string; formData?: FormData; signal?: AbortSignal }

export async function apiRequest<T>(path: string, opts: RequestOptions = {}): Promise<T> {
  let res: Response;
  try {
    res = await fetch(`${API_BASE}${path}`, {
      method: opts.method ?? 'GET',
      credentials: 'include',
      headers: opts.formData ? undefined : {'Content-Type': 'application/json'},
      body: opts.formData ? opts.formData : opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
      signal: opts.signal,
      headers: {...}
    });
  } catch { throw new NetworkError(); }
  ... parse
}
```
