/** Format integer cents as ¥xx.xx. Never use floats for money math. */
export function formatCents(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(Math.trunc(cents));
  const yuan = Math.floor(abs / 100);
  const rem = abs % 100;
  return `${sign}¥${yuan}.${rem.toString().padStart(2, '0')}`;
}
export function yuanToCents(yuan: number): number { return Math.round(yuan * 100); }
export function centsToYuan(cents: number): number { return cents / 100; }
export function sumCents(values: number[]): number { return values.reduce((a,b)=>a+b,0); }
```
