import type { MealPeriod } from '../lib/mealSlot';
import type { SpiceLevel, TastePreference } from '../lib/constants';

/**
 * API DTO types. These mirror the contract the backend exposes under
 * `${VITE_API_BASE_URL}` (default `/api`). See API.md for the authoritative
 * contract once the backend publishes it.
 */

export type Role = 'EMPLOYEE' | 'ADMIN';

export interface User {
  id: number;
  email: string;
  role: Role;
}

export interface OptionItem {
  id: number;
  name: string;
  extraPriceCents: number;
}

export interface OptionGroup {
  id: number;
  name: string;
  required: boolean;
  /** Single-choice groups use min=max=1; multi-choice use max>1. */
  minSelections: number;
  maxSelections: number;
  items: OptionItem[];
}

export interface Dish {
  id: number;
  name: string;
  description: string;
  priceCents: number;
  categories: string[];
  protein: string | null;
  spiceLevel: SpiceLevel;
  allergens: string[];
  imageUrl: string | null;
  listed: boolean;
  /** Present on employee menu queries; remaining orderable stock for the day. */
  availableQuantity?: number;
  optionGroups: OptionGroup[];
}

export interface PagedResult<T> {
