const AuthContext = createContext...
export function AuthProvider({children}) {
  const queryClient = useQueryClient();
  const { data, isLoading } = useQuery({ queryKey: ['auth','me'], queryFn: fetchCurrentUser, retry: false, staleTime: 60_000 });
  const setUser = (u) => queryClient.setQueryData(['auth','me'], u);
  ...
}
export const useAuth = () => useContext(AuthContext);
```

