{"file_path":"/Users/chengleming/IdeaProjects/WebBoxAICodingProject/frontend/src/features/menu/recommendation.ts","content":"import type { Dish, Preferences } from '../../shared/api/types';

/**
 * Client-side recommendation scoring used for highlighting and for ordering
 * when "Recommended for me" is enabled. Category match weighs more than an
 * exact spice-level match. The backend may apply the same rule server-side
 * when `recommended=true` is passed; the client sort keeps behavior
 * consistent regardless.
 */
export function recommendationScore(dish: Dish, preferences: Preferences): number {
  let score = 0;
  if (dish.categories.some((c) => preferences.categories.includes(c))) {
    score += 2;
  }
  if (preferences.spiceLevel && dish.spiceLevel === preferences.spiceLevel) {
    score += 1;
  }
  return score;
}

export function isRecommended(dish: Dish, preferences: Preferences): boolean {
  return recommendationScore(dish, preferences) > 0;
}

export function sortByRecommendation(dishes: Dish[], preferences: Preferences): Dish[] {
  return [...dishes].sort((a, b) => recommendationScore(b, preferences) - recommendationScore(a, preferences));
}

/** Allergens of the dish that the employee tracks in preferences. */
export function allergenHits(dish: Dish, preferences: Preferences): string[] {
  return dish.allergens.filter((a) => preferences.allergens.includes(a));
}
"}

