              setPage(1);
            }}
            style={{ width: 280 }}
            aria-label={copy.common.search}
          />
          <Select
            allowClear
            placeholder={copy.console.categoryFilter}
            style={{ width: 200 }}
            options={(categoriesQuery.data ?? []).map((c) => ({ label: c, value: c }))}
            value={category}
            onChange={(value) => {
              setCategory(value ?? null);
              setPage(1);
            }}
            aria-label={copy.console.categoryFilter}
          />
        </Space>

        {dishesQuery.isError ? (
          <ErrorView error={dishesQuery.error} onRetry={() => dishesQuery.refetch()} />
        ) : (
          <Table<Dish>
            rowKey="id"
            loading={dishesQuery.isLoading}
            columns={columns}
            dataSource={dishesQuery.data?.items ?? []}
            scroll={{ x: 720 }}
            pagination={{
              current: page,
              pageSize: PAGE_SIZE,
              total: dishesQuery.data?.total ?? 0,
              onChange: setPage,
              showSizeChanger: false,
            }}
          />
        )}
      </Space>

