}

export function fetchMenu(params: MenuQueryParams): Promise<MenuResult> {
  const search = new URLSearchParams();
  if (params.date) search.set('date', params.date);
  if (params.keyword) search.set('q', params.keyword);
  for (const category of params.categories) {
    search.append('categories', category);
  }
  search.set('page', String(params.page));
  search.set('size', String(params.size));
  return apiRequest<MenuResult>(`/menu?${search.toString()}`);
}

export function fetchDishDetail(dishId: number, date?: string): Promise<Dish> {
  const query = date ? `?date=${encodeURIComponent(date)}` : '';
  return apiRequest<Dish>(`/menu/${dishId}${query}`);
}

/**
 * No categories dictionary endpoint exists yet; derive distinct categories
 * from a broad menu fetch. Track as a backend contract gap.
 */
export async function fetchMenuCategories(): Promise<string[]> {
  const result = await fetchMenu({ keyword: '', categories: [], page: 0, size: 100 });
  return [...new Set(result.items.map((d) => d.category).filter(Boolean))].sort();
}

/** Server-resolved nearest orderable slot (authoritative over client time). */
export function fetchSlotSuggestion(): Promise<SlotSuggestion> {
  return apiRequest<SlotSuggestion>('/orders/suggestion');
}
"}

{"file_path":"/Users/chengleming/IdeaProjects/WebBoxAICodingProject/frontend/src/features/menu/recommendation.ts","content":"import type { Dish, Preferences } from '../../shared/api/types';

/**
 * Client-side recommendation scoring used for highlighting and ordering when
 * "Recommended for me" is enabled. Category match weighs more than an exact
 * spice-level match. (The toggle itself is a client-side preference; the
 * backend preferences payload has no such field yet.)
 */
export function recommendationScore(dish: Dish, preferences: Preferences): number {
  let score = 0;
  if (dish.category && preferences.preferredCategories.includes(dish.category)) {
    score += 2;
  }
  if (preferences.spicePreference && dish.spiceLevel === preferences.spicePreference) {
    score += 1;
  }
  return score;
}

export function isRecommended(dish: Dish, preferences: Preferences): boolean {
  return recommendationScore(dish, preferences) > 0;
}

export function sortByRecommendation(dishes: Dish[], preferences: Preferences): Dish[] {
  return [...dishes].sort((a, b) => recommendationScore(b, preferences) - recommendationScore(a, preferences));
}

/** Allergens of the dish that the employee tracks in preferences. */
export function allergenHits(dish: Dish, preferences: Preferences): string[] {
  return dish.allergens.filter((a) => preferences.allergens.includes(a));
}
"}

