          extra={[
            <Button type="primary" key="orders" href="/orders">
              {copy.checkout.viewOrders}
            </Button>,
            <Button key="menu" href="/menu">
              {copy.checkout.backToMenu}
            </Button>,
          ]}
        />
      </div>
    );
