    return (
      <div className="webox-page">
        <EmptyView description={copy.checkout.emptyNotice} />
        <div style={{ textAlign: 'center' }}>
          <Button type="primary" href="/menu">
            {copy.checkout.backToMenu}
          </Button>
        </div>
      </div>
