        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, justifyContent: 'space-between' }}>
          <Typography.Title level={3} style={{ margin: 0 }}>
            {copy.console.dishesTitle}
          </Typography.Title>
          <Button
            type="primary"
            icon={<PlusOutlined />}
            onClick={() => {
              setEditingDish(null);
              setCreating(true);
            }}
          >
            {copy.console.newDish}
          </Button>
        </div>
        <Space wrap>
          <Input.Search
            placeholder={copy.console.searchPlaceholder}
            allowClear
            maxLength={MAX_SEARCH_LENGTH}
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            onSearch={(value) => {
              setSubmittedKeyword(value.trim().slice(0, MAX_SEARCH_LENGTH));
              setPage(1);
            }}
            style={{ width: 280 }}
            aria-label={copy.common.search}
          />
          <Select
            allowClear
            placeholder={copy.console.categoryFilter}
            style={{ width: 200 }}
            options={categoryOptions.map((c) => ({ label: c, value: c }))}
            value={category}
            onChange={(value) => {
              setCategory(value ?? null);
              setPage(1);
            }}
            aria-label={copy.console.categoryFilter}
          />
        </Space>

        {dishesQuery.isError ? (
          <ErrorView error={dishesQuery.error} onRetry={() => dishesQuery.refetch()} />
        ) : (
          <Table<Dish>
            rowKey="id"
            loading={dishesQuery.isLoading}
            columns={columns}
            dataSource={pagedDishes}
            scroll={{ x: 720 }}
            pagination={{
              current: page,
              pageSize: PAGE_SIZE,
              total: dishesQuery.data?.length ?? 0,
              onChange: setPage,
              showSizeChanger: false,
            }}
          />
        )}
      </Space>

      <DishEditDrawer
        dish={editingDish}
        creating={creating}
        categoryOptions={categoryOptions}
        onClose={() => {
          setEditingDish(null);
          setCreating(false);
        }}
      />
    </div>
  );
}
